<?php declare(strict_types=1); use FastWebsite\Core\View; $value=static fn(string$field):string=>(string)($values[$field]??'');$editing=is_int($unitId);$published=$editing&&$currentStatus==='published';$action=$editing?$baseUrl.'admin/research/'.$unitId:$baseUrl.'admin/research'; ?>
