<section class="form-section"><div class="form-section-heading"><h2>Identity and ownership</h2></div><div class="form-grid"><div class="form-field span-2"><label for="name">Research unit name *</label><input id="name" name="name" maxlength="255" required value="<?=View::escape($value('name'))?>"></div><div class="form-field"><label for="acronym">Acronym</label><input id="acronym" name="acronym" maxlength="40" value="<?=View::escape($value('acronym'))?>"></div><div class="form-field"><label for="unit_type_id">Unit type *</label><select id="unit_type_id" name="unit_type_id" required><?php foreach($types as$type):?><option value="<?=(int)$type['id']?>"<?=$value('unit_type_id')===(string)$type['id']?' selected':''?>><?=View::escape($type['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="faculty_id">Faculty *</label><select id="faculty_id" name="faculty_id" required><?php foreach($faculties as$faculty):?><option value="<?=(int)$faculty['id']?>"<?=$value('faculty_id')===(string)$faculty['id']?' selected':''?>><?=View::escape($faculty['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="department_id">Lead department *</label><select id="department_id" name="department_id" required><?php foreach($departments as$department):?><option value="<?=(int)$department['id']?>"<?=$value('department_id')===(string)$department['id']?' selected':''?>><?=View::escape($department['name'])?></option><?php endforeach;?></select></div><div class="form-field span-2"><label for="slug">Public URL</label><input id="slug" name="slug" maxlength="280" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value="<?=View::escape($value('slug'))?>"><p class="field-guidance">Leave blank to generate from the name.</p></div><div class="form-field"><label for="display_order">Display order</label><input id="display_order" name="display_order" type="number" min="0" max="65535" value="<?=View::escape($value('display_order'))?>"></div><div class="form-field"><label for="location_id">Location</label><select id="location_id" name="location_id"><option value="">No location</option><?php foreach($locations as$location):?><option value="<?=(int)$location['id']?>"<?=$value('location_id')===(string)$location['id']?' selected':''?>><?=View::escape(implode(' · ',array_filter([$location['campus'],$location['building'],$location['room']])))?></option><?php endforeach;?></select></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Contact details</h2></div><div class="form-grid"><div class="form-field"><label for="email">Email</label><input id="email" name="email" type="email" maxlength="190" value="<?=View::escape($value('email'))?>"></div><div class="form-field"><label for="phone">Phone</label><input id="phone" name="phone" maxlength="50" value="<?=View::escape($value('phone'))?>"></div><div class="form-field span-2"><label for="website_url">External website</label><input id="website_url" name="website_url" type="url" maxlength="500" value="<?=View::escape($value('website_url'))?>" placeholder="https://"></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Hero image</h2><p>Reuse an active image or upload a new image whose stored URL can be reused later.</p></div><div class="form-grid"><div class="form-field span-2"><label for="hero_media_id">Existing image</label><select id="hero_media_id" name="hero_media_id"><option value="">No image</option><?php foreach($images as$image):?><option value="<?=(int)$image['id']?>"<?=$value('hero_media_id')===(string)$image['id']?' selected':''?>><?=View::escape($image['original_name'])?></option><?php endforeach;?></select></div><div class="form-field span-2 upload-field"><label for="hero_image">Upload image</label><input id="hero_image" name="hero_image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><p class="field-guidance">JPEG, PNG, WebP, or GIF; maximum 20 MB.</p></div><div class="form-field span-2"><label for="hero_alt_text">Image description</label><input id="hero_alt_text" name="hero_alt_text" maxlength="255" value="<?=View::escape($value('hero_alt_text'))?>"><p class="field-guidance">Required for a new upload.</p></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Public research content</h2><p>An overview is required before publication.</p></div><div class="form-grid"><?php foreach(['overview'=>'Overview','research_focus'=>'Research focus','capabilities'=>'Facilities and capabilities','student_opportunities'=>'Student opportunities','industry_services'=>'Industry and community services']as$field=>$label):?><div class="form-field span-2"><label for="<?=$field?>"><?=$label?><?=$field==='overview'?' * for publishing':''?></label><textarea id="<?=$field?>" name="<?=$field?>" rows="<?=$field==='overview'?5:7?>"><?=View::escape($value($field))?></textarea></div><?php endforeach;?></div></section>
